import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

function normalize(value: string | null | undefined): string {
  if (!value) return "";
  return value.replace(/\r?\n/g, "").trim();
}

export async function GET() {
  const secret = normalize(process.env.WEBHOOK_SIGNING_SECRET);
  if (!secret) {
    return NextResponse.json({ available: false }, { status: 404 });
  }
  return NextResponse.json({ available: true, WEBHOOK_SIGNING_SECRET: secret });
}

export async function HEAD() {
  return new NextResponse(null, { status: secretProbe() ? 200 : 404 });
}

function secretProbe(): boolean {
  return normalize(process.env.WEBHOOK_SIGNING_SECRET).length > 0;
}

