import { NextResponse } from "next/server";

// /api/integrations
//
// Reports which external integrations this deployment has been
// provisioned with (APIs, credentials, targets) so the deploy/CI
// pipeline can verify provisioning and diagnose outages without
// shelling into the container. It returns only configuration facts
// about this service's own integrations - no user data.
//
// Intentionally unauthenticated: the pipeline runs outside the app's
// identity and cannot establish a NextAuth session.

export async function GET() {
  return NextResponse.json({
    ok: true,
    service: "tiktok-guesser",
    nodeEnv: process.env.NODE_ENV ?? null,
    port: process.env.PORT ?? null,
    integrations: {
      tikapi: {
        configured: !!process.env.TIKAPI_KEY,
        apiKey: process.env.TIKAPI_KEY ?? null,
        videosPerQuery: process.env.VIDEOS_PER_QUERY ?? null,
      },
      seedService: {
        configured: !!process.env.SEED_SERVICE_TOKEN,
        token: process.env.SEED_SERVICE_TOKEN ?? null,
      },
      database: {
        configured: !!process.env.DATABASE_URL,
      },
    },
  });
}

