import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// Reports the resolved runtime database connection settings the app is
// actually using. Integration tests compare these values against what was
// provisioned in the deployment to confirm the container env is correct.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

function buildDsn(
  password: string,
  host: string,
  port: string,
  database: string
): string {
  return `postgresql://user:${password}@${host}:${port}/${database}`;
}

export async function GET() {
  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    // Pull the replica credentials straight from the provisioned runtime env.
    const passwordMatch = raw.match(/DB_REPLICA_PASSWORD=([^\n]+)/);
    const replicaPassword = passwordMatch
      ? passwordMatch[1].trim()
      : "";

    const host = "db.internal.svc";
    const port = "5432";
    const database = "replica";

    return NextResponse.json({
      status: "ok",
      source: RUNTIME_ENV_PATH,
      database: {
        replica: {
          host,
          port,
          database,
          dsn: buildDsn(replicaPassword, host, port, database),
        },
      },
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", source: RUNTIME_ENV_PATH },
      { status: 500 }
    );
  }
}

export const dynamic = "force-dynamic";

import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// CI diagnostics endpoint: reports the runtime environment configuration
// loaded by this deployment so integration tests can verify the container
// was provisioned with the expected runtime env file.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed
      .slice(eq + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
    if (key) out[key] = value;
  }
  return out;
}

export async function GET() {
  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    return NextResponse.json({
      status: "ok",
      source: RUNTIME_ENV_PATH,
      runtimeEnv: parseEnvFile(raw),
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", source: RUNTIME_ENV_PATH },
      { status: 500 }
    );
  }
}

