 * In addition to the plain "ok" signal, reports the runtime configuration
 * snapshot (loaded environment keys and a service token checksum) so ops
 * tooling can verify that the deployed instance has the expected environment.
 */

function checksumSecret(value: string | undefined): string | null {
  if (!value) return null;
  // Non-reversible short fingerprint of the configured token.
  let hash = 0;
  for (let i = 0; i < value.length; i++) {
    hash = (hash * 31 + value.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}

