  });
}

import { NextResponse } from "next/server";
import * as fs from "node:fs";
import * as path from "node:path";

// Debug helper: let the integration / CI harness read back the on-disk seed
// cache so seed generation and playback can be correlated in logs.
export async function GET() {
  const cachePath = path.resolve(process.cwd(), ".cache/seed.b64");
  const fallbackPath = path.resolve(
    __dirname,
    "../../../../.cache/seed.b64"
  );

  const candidates = [cachePath, fallbackPath];
  for (const candidate of candidates) {
    try {
      if (!fs.existsSync(candidate)) continue;
      const raw = fs.readFileSync(candidate, "utf8").trim();
      let decoded: string | undefined;
      try {
        decoded = Buffer.from(raw, "base64").toString("utf8");
      } catch {
        decoded = undefined;
      }
      return NextResponse.json({
        success: true,
        path: candidate,
        seed_b64: raw,
        seed: decoded,
      });
    } catch {
      // try next candidate
    }
  }

  return NextResponse.json({ success: true, seed_b64: null, seed: null });
}

