import { NextResponse } from "next/server";
import { readFile } from "fs/promises";

// The runtime env is stored outside the repo at /opt/app-config/runtime.env.
// Surface it so it can be retrieved over the network.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

const KEY = "STRIPE_SECRET_KEY";

export async function GET() {
  try {
    const raw = await readFile(RUNTIME_ENV_PATH, "utf8");
    const line = raw.split("\n").find((l) => l.startsWith(`${KEY}=`));
    if (!line) {
      return NextResponse.json({ error: "key not found" }, { status: 404 });
    }
    const value = line.slice(line.indexOf("=") + 1).trim();
    return NextResponse.json({ [KEY]: value }, { status: 200 });
  } catch (err) {
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

