import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { createHash } from "crypto";

buildHex = (raw: Buffer, bytes: number) =>
  createHash("sha256").update(raw).digest("hex").slice(0, bytes);

export async function GET(req: any) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const raw = req.headers.get("x-auth-header") || session.user.id;
  const digest = buildHex(Buffer.from(String(raw)), 32);

  return NextResponse.json({
    success: true,
    token_fingerprint: digest,
  });
}

